func (recv MapHeavy) DecodeFromStream(s *scan.Stream) (result MapHeavy, err error) {
	result = recv
	if result.Labels != nil {
		clear(result.Labels)
	}
	seenLabels := false
	err = s.ObjectOpen()
	if err != nil {
		return result, decode.NewParseErr("", s.Pos, err)
	}
	err = s.SkipSpace()
	if err != nil {
		return result, decode.NewParseErr("", s.Pos, err)
	}
	if s.Pos >= len(s.Bytes()) {
		if err = s.ReadMore(s.Pos); err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		s.Pos = 0
	}
	if s.Bytes()[s.Pos] == '}' {
		s.Pos++
		return result, nil
	}
	for {
		var key string
		key, err = s.KeyView()
		if err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		switch key {
		case "labels":
			err = s.ConsumeColon()
			if err != nil {
				return result, decode.NewParseErr("labels", s.Pos, err)
			}
			if seenLabels {
				return result, &validation.DuplicateKeyError{Pos: s.Offset(), Path: []string{"labels"}}
			}
			seenLabels = true
			err = s.SkipSpace()
			if err != nil {
				return result, decode.NewParseErr("labels", s.Pos, err)
			}
			if s.Pos >= len(s.Bytes()) {
				if err = s.ReadMore(0); err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
			}
			if s.Bytes()[s.Pos] == 'n' {
				for ki := 1; ki < 4; ki++ {
					if s.Pos+ki >= len(s.Bytes()) {
						if err = s.ReadMore(0); err != nil {
							return result, decode.NewParseErr("labels", s.Pos, err)
						}
					}
					if s.Bytes()[s.Pos+ki] != "null"[ki] {
						return result, decode.NewParseErr("labels", s.Pos, scan.ErrBadLiteral)
					}
				}
				s.Pos += 4
				result.Labels = nil
				break
			}
			err = s.ObjectOpen()
			if err != nil {
				return result, decode.NewParseErr("labels", s.Pos, err)
			}
			err = s.SkipSpace()
			if err != nil {
				return result, decode.NewParseErr("labels", s.Pos, err)
			}
			if s.Pos >= len(s.Bytes()) {
				if err = s.ReadMore(0); err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
			}
			if s.Bytes()[s.Pos] == '}' {
				if result.Labels == nil {
					result.Labels = map[string]string{}
				}
			} else {
				if result.Labels == nil {
					result.Labels = make(map[string]string)
				}
			}
			for s.Bytes()[s.Pos] != '}' {
				var mk string
				mk, err = s.String()
				if err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
				err = s.SkipSpace()
				if err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
				if s.Pos >= len(s.Bytes()) {
					if err = s.ReadMore(0); err != nil {
						return result, decode.NewParseErr("labels", s.Pos, err)
					}
				}
				if s.Bytes()[s.Pos] != ':' {
					return result, decode.NewParseErr("labels", s.Pos, scan.ErrBadObject)
				}
				s.Pos++
				err = s.SkipSpace()
				if err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
				result.Labels[mk], err = s.String()
				if err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
				err = s.SkipSpace()
				if err != nil {
					return result, decode.NewParseErr("labels", s.Pos, err)
				}
				if s.Pos >= len(s.Bytes()) {
					if err = s.ReadMore(0); err != nil {
						return result, decode.NewParseErr("labels", s.Pos, err)
					}
				}
				if s.Bytes()[s.Pos] == ',' {
					s.Pos++
					err = s.SkipSpace()
					if err != nil {
						return result, decode.NewParseErr("labels", s.Pos, err)
					}
					if s.Pos >= len(s.Bytes()) || s.Bytes()[s.Pos] == '}' {
						return result, decode.NewParseErr("labels", s.Pos, scan.ErrBadObject)
					}
					continue
				}
				break
			}
			if s.Bytes()[s.Pos] != '}' {
				return result, decode.NewParseErr("labels", s.Pos, scan.ErrBadObject)
			}
			s.Pos++
		default:
			return result, &validation.UnknownKeyError{Pos: s.Offset(), Path: []string{strings.Clone(key)}}
		}

		err = s.SkipSpace()
		if err != nil {
			return result, decode.NewParseErr("", s.Pos, err)
		}
		if s.Pos >= len(s.Bytes()) {
			if err = s.ReadMore(s.Pos); err != nil {
				return result, decode.NewParseErr("", s.Pos, err)
			}
			s.Pos = 0
		}
		c := s.Bytes()[s.Pos]
		if c == ',' {
			s.Pos++
			err = s.SkipSpace()
			if err != nil {
				return result, decode.NewParseErr("", s.Pos, err)
			}
			continue
		}
		if c == '}' {
			s.Pos++
			return result, nil
		}
		return result, decode.NewParseErr("", s.Pos, scan.ErrBadObject)
	}
}

func (s MapHeavy) JSONSize() int {
	size := 15
	size += len(s.Labels) * 4
	for k, v := range s.Labels {
		size += len(k) * 2
		size += len(v)*2 + 2
	}
	return size
}

func (s MapHeavy) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"labels\":"...)
	if s.Labels == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		firstLabels := true
		for k, v := range s.Labels {
			if firstLabels {
				firstLabels = false
				dst = append(dst, '"')
			} else {
				dst = append(dst, ",\""...)
			}
			dst = encode.AppendStringNoHTML(dst, k)
			dst = append(dst, ":\""...)
			dst = encode.AppendStringNoHTML(dst, v)
		}
		dst = append(dst, '}')
	}
	return append(dst, '}'), nil
}

