func (s PostalAddress) JSONSize() int {
	size := 80
	size += len(s.City) * 2
	size += len(s.Country) * 2
	size += s.Geo.JSONSize()
	size += len(s.Line1) * 2
	size += len(s.Line2) * 2
	size += len(s.PostalCode) * 2
	size += len(s.State) * 2
	return size
}

